//! A SkyFrame holding plain Axis objects, as `astLoadFrame` gives one read
//! from a description with no `Ax<n>` objects (frame.c:15227), behaves as
//! C's does: Format, Unit, formatting and unformatting come from the plain
//! Axis; setting AsTime replaces the axis with a SkyAxis carrying its
//! attributes (skyframe.c `SetAsTime`); and picking the axis out gives a
//! SkyAxis (skyframe.c `SubFrame`).
//!
//! `sky_plain_axis_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/sky_plain_axis_probe.c`.

use crate::common::native_dump;
#[path = "sky_plain_axis_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{BasicFrame, Frame, pick_axes};
use starlink_ast::{AnyObject, from_native_string};

fn text(lines: &[&str]) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

fn axes(f: &dyn Frame) -> [cases::Axis; 2] {
    let leak = |s: String| -> &'static str { Box::leak(s.into_boxed_str()) };
    [1, 2].map(|axis| {
        (
            leak(f.format_str(axis).unwrap()),
            leak(f.unit(axis).unwrap()),
            leak(f.format(axis, 1.2345).unwrap()),
            f.unformat(axis, "1.5").unwrap(),
        )
    })
}

#[test]
fn a_skyframe_with_plain_axes_behaves_as_c_does() {
    let AnyObject::SkyFrame(mut sky) = from_native_string(&text(cases::TEXT)).unwrap() else {
        panic!("not a SkyFrame");
    };
    assert_eq!(axes(&sky), cases::STEPS[0].1, "{}", cases::STEPS[0].0);

    sky.set_as_time(1, true).unwrap();
    assert_eq!(axes(&sky), cases::STEPS[1].1, "{}", cases::STEPS[1].0);

    let dump = native_dump(&AnyObject::SkyFrame(sky.clone())).unwrap();
    assert_eq!(dump, text(cases::DUMP));

    let (picked, _) = pick_axes(&sky, &[2]).unwrap();
    let picked = picked
        .as_any()
        .downcast_ref::<BasicFrame>()
        .expect("the picked Frame is a plain Frame")
        .clone();
    let dump = native_dump(&AnyObject::BasicFrame(picked)).unwrap();
    assert_eq!(dump, text(cases::PICKED_2));
}
